import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2023-03-30","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-03-30","date":"2023-03-30T00:00:00.000Z","updated":"2023-04-06T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-03-30.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-03-30.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_Performance_Meeting_2023-03-30.md"};function o(n,e,s,c,h,u){return t(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph 性能会议 <strong>日期：</strong> 2023年3月30日 <strong>主持人：</strong> Marcus</p><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ol><li><strong>新PR介绍：</strong> 介绍了新增的零API到RW Casey，旨在创建一个无后端存储的REST API，用于隔离HTTP前端基准测试，优化Boost前端，并对比HTTP/3前端的工作。</li><li><strong>性能优化：</strong><ul><li>Mark Kogan进行了一些初步的HS基准测试，显示了较好的改进。</li><li>讨论了Beast前端的SSL连接开销，特别是在高负载或多客户端情况下的瓶颈。</li></ul></li><li><strong>其他更新PR：</strong><ul><li>推进了Mark提出的booster accumulation想法，旨在批量处理键值存储更新，以提高整体吞吐量。</li><li>解决了BlueFS的碎片问题，相关方法已批准，等待QA。</li><li>新的Crimson性能套件表现良好，可开始收集数据并与Amazon进行比较。</li><li>更新了M clock恢复和backfill成本，特别是在小对象工作负载下的性能改进。</li></ul></li><li><strong>会议工具变更：</strong> 从下周开始，会议将切换到Jitsi进行。</li></ol><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h4><ul><li>性能优化工具的使用和测量方法。</li><li>新的性能改进提案和其潜在影响。</li><li>会议工具的变更及其影响。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ul><li>确认了新的性能工具的使用和测量方法。</li><li>同意了会议工具的变更。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划： <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划：&quot;">​</a></h4><ul><li>继续对新的性能工具进行测试和优化。</li><li>完成Mark的booster accumulation提案的更新和测试。</li><li>开始使用新的Crimson性能套件进行数据收集和分析。</li><li>切换到Jitsi进行后续的会议。</li></ul><p><strong>会议结束：</strong> 感谢所有参与者的参与，并期待下周在Jitsi上的再次会议。</p>',11)])])}const p=a(r,[["render",o]]);export{d as __pageData,p as default};
